        self.build_geom()
        self.set_slip(slip)

    def nid(self, i, j):
        return j * self.nx + i

    def build_geom(self):
        s = self.s
        cell = s.cell
        self.edges = []  # (u, v, L, [(grade, code, dh)...])
        K = 5
        for j in range(self.ny):
            for i in range(self.nx):
                u = self.nid(i, j)
                x0, y0 = i * cell, j * cell
                for di, dj in NB:
                    ii, jj = i + di, j + dj
                    if not (0 <= ii < self.nx and 0 <= jj < self.ny):
                        continue
                    dx, dy = di * cell, dj * cell
                    L = math.hypot(dx, dy)
                    ux, uy = dx / L, dy / L
                    segs = []
                    ok = True
                    prev_h = s.h[j][i]
                    for k in range(K):
                        f = (k + 0.5) / K
                        px, py = x0 + dx * f, y0 + dy * f
                        h, gx, gy, code = s.sample(px, py)
                        if math.hypot(gx, gy) > SLOPE_OK:
                            ok = False
                            break
                        f2 = k / K
                        _, gx2, gy2, _ = s.sample(x0 + dx * f2 + 1e-6, y0 + dy * f2 + 1e-6)
                        if math.hypot(gx2, gy2) > SLOPE_OK:
                            ok = False
                            break
                        hn = s.elevation(x0 + dx * (k + 1) / K, y0 + dy * (k + 1) / K)
                        segs.append((gx * ux + gy * uy, code, hn - prev_h))
                        prev_h = hn
                    if not ok:
                        continue
                    self.edges.append((u, ii + jj * self.nx, L, segs))

    def set_slip(self, slip):
        P = PHYSICS
        self.adj = [[] for _ in range(self.N)]
        self.radj = [[] for _ in range(self.N)]
        K = 5
        for (u, v, L, segs) in self.edges:
            t = e = 0.0
            seglen = L / K
            for grade, code, dh in segs:
                name = TERRAIN_CODES[code]
                sl = slip[name] + P["slip_grade_gain"][name] * max(0.0, grade)
                sl = min(0.9, sl)
                wheel = seglen / (1 - sl)
                t += wheel / 5.0
                e += wheel * P["drive_cost_per_wheel_m"][name] + 2.0 * max(0.0, dh)
            c = t + E_W * e
            self.adj[u].append((v, c, t, e))
            self.radj[v].append((u, c, t, e))

