        adj = self.radj if rev else self.adj
        dist = [1e18] * self.N
        pred = [-1] * self.N
        tt = [0.0] * self.N
        ee = [0.0] * self.N
        dist[src] = 0.0
        h = [(0.0, src)]
        while h:
            d, u = heapq.heappop(h)
            if d > dist[u]:
                continue
            for v, c, t, e in adj[u]:
                nd = d + c
                if nd < dist[v]:
                    dist[v] = nd
                    pred[v] = u
                    tt[v] = tt[u] + t
                    ee[v] = ee[u] + e
                    heapq.heappush(h, (nd, v))
        return dist, pred, tt, ee

    def near(self, x, y):
        c = self.s.cell
        i = min(self.nx - 1, max(0, int(round(x / c))))
        j = min(self.ny - 1, max(0, int(round(y / c))))
        return self.nid(i, j)

    def xy(self, n):
        return (n % self.nx) * self.s.cell, (n // self.nx) * self.s.cell


