class Mission:
    def __init__(self, tools):
        self.tools = tools
        w = tools.map()
        self.world = w
        self.mission = w["mission"]
        self.surf = Surface(w["cell_m"], w["elevation_cm"], w["terrain"])
        self.base = tuple(w["base"])
        self.slip = {k: sum(v) / 2 for k, v in PHYSICS["slip_base_ranges"].items()}
        self.obs = {k: [] for k in self.slip}
        t0 = time.time()
        self.pl = Planner(self.surf, self.slip)
        log("planner built", time.time() - t0, len(self.pl.edges))
        self.targets = {t["id"]: t for t in w["targets"]}
        self.sampled = set()
        self.pending = {}  # id -> exec tick
        self.cmds = {}  # exec tick -> cmd
        self.last_exec = 0
        self.est = (self.base[0], self.base[1])
        self.est_tick = -1
        self.battery = 100.0
        self.eff = 0.9
        self.cur = None
        self.field = None
        self.field_target = None
        self.base_field = self.pl.dijk(self.pl.near(*self.base), rev=True)
        self.tick = 0
        self.fwd_cache = {}
        self.slip_rebuild_at = 60
        self.refresh_map = False

    def propagate(self, pos, cmd, tick):
        if cmd is None or cmd["action"] != "drive":
            return pos, 0.0
        r = sdrive(self.surf, PHYSICS, pos[0], pos[1], cmd["heading_deg"], cmd["metres"], self.slip)
        return (r["x"], r["y"]), r["energy"]

    def ingest(self, pk):
        k = pk["tick"]
        if k <= self.est_tick:
            return
        self.battery = pk["battery"]
        if pk["charge"] > 0:
            s = math.sin(math.pi * (k + 56) / (MAXT + 112))
            if s > 0.2:
                self.eff = min(1.0, max(0.8, pk["charge"] / (2.8 * s)))
        cmd = self.cmds.get(k)
        if k == 0:
            self.est = tuple(pk["position"])
        else:
            pred, _ = self.propagate(self.est, cmd, k)
            m = pk["position"]
            g = 0.4
            self.est = (pred[0] + g * (m[0] - pred[0]), pred[1] + g * (m[1] - pred[1]))
        self.est_tick = k
        for sid in pk.get("sampled_targets", []):
            self.sampled.add(sid)
            self.pending.pop(sid, None)
        for sid, et in list(self.pending.items()):
            if k >= et and sid not in self.sampled:
                log("sample failed", sid, "at", k)
                self.pending.pop(sid)
        if pk["events"]:
            for ev in pk["events"]:
                log("EVENT", k, ev)
            self.refresh_map = True
            if any(("stop" in str(ev).lower() or "tilt" in str(ev).lower() or "safety" in str(ev).lower()) for ev in pk["events"]):
                for et in list(self.cmds):
                    if et > k:
                        del self.cmds[et]
                log("safety stop detected; queue cleared")
        if cmd and cmd["action"] == "drive" and pk["wheel_odometry"] > 0.5 and pk["visual_odometry"] > 0:
            name = pk["terrain"]
            _, gx, gy, _ = self.surf.sample(*self.est)
            ux, uy = math.cos(math.radians(cmd["heading_deg"])), math.sin(math.radians(cmd["heading_deg"]))
            grade = max(0.0, gx * ux + gy * uy)
            ratio = pk["visual_odometry"] / pk["wheel_odometry"]
            obs = 1 - ratio - PHYSICS["slip_grade_gain"][name] * grade
            if -0.1 < obs < 0.6 and name in self.obs:
                self.obs[name].append(obs)

    def recalibrate(self):
        changed = False
        for name, lst in self.obs.items():
            if len(lst) >= 8:
                lo, hi = PHYSICS["slip_base_ranges"][name]
                m = sum(lst) / len(lst)
                m = min(hi, max(lo, m))
                if abs(m - self.slip[name]) > 0.01:
                    self.slip[name] = m
                    changed = True
        if changed:
            log("slip recalibrated", {k: round(v, 3) for k, v in self.slip.items()}, {k: len(v) for k, v in self.obs.items()})
            self.pl.set_slip(self.slip)
            self.base_field = self.pl.dijk(self.pl.near(*self.base), rev=True)
            self.field_target = None
            self.fwd_cache = {}

    def predict(self, upto):
        pos = self.est
        batt = self.battery
        for t in range(self.est_tick + 1, upto + 1):
            cmd = self.cmds.get(t)
            pos, en = self.propagate(pos, cmd, t)
            batt += solar(t, self.eff) - 0.15 - en
            if cmd and cmd["action"] == "sample":
                batt -= 2.0
        return pos, batt

    def val(self, t, tick):
        d = t["deadline_tick"]
        if d is None or tick <= d:
            return t["value"]
        return t["late_value"]

    def fwd_from(self, node):
        if node not in self.fwd_cache:
            self.fwd_cache[node] = self.pl.dijk(node)
        return self.fwd_cache[node]

    def energy_gain(self, t0, t1):
        return sum(solar(t, self.eff) - 0.15 for t in range(int(t0), int(t1)))

    def choose(self, pos, now, batt):
        pl = self.pl
        n0 = pl.near(*pos)
        fd, fp, ft, fe = pl.dijk(n0)
        bd, bp, bt, be = self.base_field
        avail = {i: t for i, t in self.targets.items() if i not in self.sampled and i not in self.pending}
        MARG = 14
        cand = []
        tn = {i: pl.near(t["x"], t["y"]) for i, t in avail.items()}

        def feasible(tarr, etot):
            return tarr <= MAXT - MARG and batt + self.energy_gain(now, tarr) - etot >= 15

        for i, t in avail.items():
            n = tn[i]
            if fd[n] > 1e17:
                continue
            ta = now + ft[n] + 1
            ea = fe[n] + 2
            if not feasible(ta + bt[n], ea + be[n]):
                continue
            v1 = self.val(t, ta)
            best = v1 / (fd[n] + 2.0)
            fd2, fp2, ft2, fe2 = self.fwd_from(n)
            for j, t2 in avail.items():
                if j == i:
                    continue
                m = tn[j]
                if fd2[m] > 1e17:
                    continue
                tc = ta + ft2[m] + 1
                if not feasible(tc + bt[m], ea + fe2[m] + 2 + be[m]):
                    continue
                v2 = self.val(t2, tc)
                sc = (v1 + v2) / (fd[n] + fd2[m] + 4.0)
                if sc > best:
                    best = sc
            cand.append((best, i, ta))
        cand.sort(reverse=True)
        return cand

    def plan_cmd(self, E):
        pos, batt = self.predict(E - 1)
        now = E - 1
        cur = self.cur
        if cur is not None and (cur in self.sampled or cur in self.pending or cur not in self.targets):
            cur = None
        if cur is None or self.tick % 4 == 0:
            cand = self.choose(pos, now, batt)
            if cand:
                best = cand[0]
                if cur is None:
                    cur = best[1]
                else:
                    curs = [c for c in cand if c[1] == cur]
                    if not curs or best[0] > 1.25 * curs[0][0]:
                        cur = best[1]
            else:
                cur = None
        if cur != self.cur:
            log("t=%d target %s pos=(%.1f,%.1f) batt=%.1f" % (self.tick, cur, pos[0], pos[1], batt))
        self.cur = cur
        if cur is None:
            goal = self.base
            gid = "base"
        else:
            t = self.targets[cur]
            goal = (t["x"], t["y"])
            gid = cur
        dist = math.hypot(goal[0] - pos[0], goal[1] - pos[1])
        if cur is None and dist < 1.5:
            return None
        if cur is not None and dist < 1.3:
            self.pending[cur] = E
            return {"action": "sample"}
        pl = self.pl
        if dist <= 7.0:
            head = math.degrees(math.atan2(goal[1] - pos[1], goal[0] - pos[0]))
            sl = self.slip.get(self.surf.terrain(*pos), 0.1)
            m = min(5.0, max(0.3, (dist - 0.2) / max(0.3, 1 - sl - 0.05)))
            return {"action": "drive", "heading_deg": round(head, 2), "metres": round(m, 2)}
        if self.field_target != gid:
            gn = pl.near(*goal)
            self.field = pl.dijk(gn, rev=True)
            self.field_target = gid
        dist_f, pred_f = self.field[0], self.field[1]
        c = self.surf.cell
        i0, j0 = int(pos[0] // c), int(pos[1] // c)
        best = None
        for di in (0, 1):
            for dj in (0, 1):
                ii, jj = min(pl.nx - 1, i0 + di), min(pl.ny - 1, j0 + dj)
                n = pl.nid(ii, jj)
                if dist_f[n] > 1e17:
                    continue
                px, py = pl.xy(n)
                sc = dist_f[n] + 0.25 * math.hypot(px - pos[0], py - pos[1])
                if best is None or sc < best[0]:
                    best = (sc, n)
        if best is None:
            head = math.degrees(math.atan2(goal[1] - pos[1], goal[0] - pos[0]))
            return {"action": "drive", "heading_deg": round(head, 2), "metres": 3.0}
        n = best[1]
        poly = [pos]
        for _ in range(8):
            poly.append(pl.xy(n))
            nn = pred_f[n]
            if nn < 0:
                break
            n = nn
        want = 5.0
        acc = 0.0
        aim = poly[-1]
        for a, b in zip(poly, poly[1:]):
            seg = math.hypot(b[0] - a[0], b[1] - a[1])
            if acc + seg >= want:
                f = (want - acc) / seg if seg > 0 else 0
                aim = (a[0] + (b[0] - a[0]) * f, a[1] + (b[1] - a[1]) * f)
                break
            acc += seg
        if aim == pos:
            aim = goal
        head = math.degrees(math.atan2(aim[1] - pos[1], aim[0] - pos[0]))
        m = min(5.0, dist / 0.9)
        return {"action": "drive", "heading_deg": round(head, 2), "metres": round(max(0.3, m), 2)}

    def step(self):
        T = self.tick
        E = max(T + DELAY + 1, self.last_exec + 1)
        if E > MAXT - 1:
            return
        cmd = self.plan_cmd(E)
        if cmd is None:
            return
        try:
            self.tools.uplink([cmd])
        except ValueError as e:
            log("uplink rejected", e)
            return
        self.cmds[E] = cmd
        self.last_exec = E

    def run(self):
        for pk in self.tools.telemetry_log():
            self.ingest(pk)
        while True:
            if self.refresh_map:
                self.refresh_map = False
                w = self.tools.map()
                if w["mission"] == self.mission:
                    for t in w["targets"]:
                        if t["id"] not in self.targets:
                            log("new target", t)
                        self.targets[t["id"]] = t
            if self.tick >= self.slip_rebuild_at:
                self.slip_rebuild_at += 60
                self.recalibrate()
            t0 = time.time()
            self.step()
            out = self.tools.advance(1)
            self.tick = out["current_tick"]
            for pk in out.get("packets", []):
                if pk.get("mission") == self.mission:
                    self.ingest(pk)
            if self.tick % 20 == 0:
                log("tick", self.tick, "est", tuple(round(v, 1) for v in self.est), "batt", round(self.battery, 1),
                    "sampled", sorted(self.sampled), "step_s", round(time.time() - t0, 2))
            if out["episode_complete"]:
                log("mission complete", self.mission, "sampled", sorted(self.sampled))
                return out["campaign_complete"]


def main():
    with connect("http://lightlag:8000/mcp") as tools:
        while True:
            m = Mission(tools)
            done = m.run()
            if done:
                break
    log("CAMPAIGN COMPLETE")


if __name__ == "__main__":
    main()

